import json, glob

# Check intermediates
files = sorted(glob.glob('/root/symb_invariant_consensus/results/folio_204_14b/intermediates/*.json'))
print(f"Found {len(files)} intermediate files")
for f in files[:3]:
    with open(f) as fh:
        d = json.load(fh)
    answers = set()
    if 'sica_result' in d and 'traces' in d['sica_result']:
        for t in d['sica_result']['traces']:
            if 'answer' in t:
                answers.add(t['answer'])
    print(f"  {f.split('/')[-1]}: answers={answers}")
    for a in answers:
        if 'text' in a.lower() or '\\' in a:
            print(f"    WARNING: LaTeX residue: {a!r}")

# Check main results
with open('/root/symb_invariant_consensus/results/folio_204_14b/folio_204_results.json') as fh:
    data = json.load(fh)
results = data.get('results', [])
print(f"\nMain results: {len(results)} entries")
for r in results[:3]:
    print(f"  {r.get('problem_id','?')}: sica={r.get('sica_answer','?')!r} sc={r.get('sc_answer','?')!r} gt={r.get('ground_truth','?')!r}")
    if 'text' in str(r.get('sica_answer','')).lower() or '\\' in str(r.get('sica_answer','')):
        print(f"    WARNING: LaTeX in sica_answer")
    if 'text' in str(r.get('sc_answer','')).lower() or '\\' in str(r.get('sc_answer','')):
        print(f"    WARNING: LaTeX in sc_answer")
PYEOF
